from pathlib import Path
class Reader:
 def __init__(self,b):self.b=b;self.i=0
 def take(self,n):v=self.b[self.i:self.i+n];self.i+=n;return v
 def u1(self):return self.take(1)[0]
 def u2(self):return int.from_bytes(self.take(2),'big')
 def u4(self):return int.from_bytes(self.take(4),'big')
def parse(path):
 r=Reader(path.read_bytes());assert r.u4()==0xcafebabe
 r.u2();major=r.u2();pool=[None]*r.u2();i=1
 while i<len(pool):
  tag=r.u1()
  if tag==1:pool[i]=r.take(r.u2()).decode('utf8',errors='replace')
  elif tag in (3,4):r.take(4)
  elif tag in (5,6):r.take(8);i+=1
  elif tag in (7,8,16,19,20):pool[i]=(tag,r.u2())
  elif tag in (9,10,11,12,17,18):pool[i]=(tag,r.u2(),r.u2())
  elif tag==15:pool[i]=(tag,r.u1(),r.u2())
  else:raise ValueError((path,tag))
  i+=1
 def cn(i):return pool[pool[i][1]]
 flags=r.u2();owner=cn(r.u2());r.u2();r.take(2*r.u2())
 def members():
  result=[]
  for _ in range(r.u2()):
   f=r.u2();n=pool[r.u2()];d=pool[r.u2()];result.append((n,d,f))
   for _ in range(r.u2()):r.u2();r.take(r.u4())
  return result
 fields=members();methods=members();refs=[]
 for v in pool:
  if isinstance(v,tuple) and v[0] in (9,10,11):
   nt=pool[v[2]];refs.append((v[0],cn(v[1]),pool[nt[1]],pool[nt[2]]))
 return {'path':str(path),'owner':owner,'major':major,'fields':fields,'methods':methods,'refs':refs,'classes':[pool[v[1]] for v in pool if isinstance(v,tuple) and v[0]==7]}
def inventory():
 return [parse(p) for p in list(Path('.').glob('**/target/classes/**/*.class'))+list(Path('.').glob('**/target/test-classes/**/*.class'))]

